INSERT INTO `articles` (`id`, `title`, `content`, `category_id`, `user_id`, `status`, `publish_at`, `created_at`, `updated_at`, `views`) VALUES
(1, 'Test 1 for Installation and Configuration', 'This is the first test article for the Installation and Configuration category', 1, 5, 'draft', '2025-05-08 12:10:00', '2025-04-23 11:06:19', '2025-06-06 20:17:29', 6),
(2, 'How To create a knowledge article', 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Fusce pharetra sagittis porta. Sed nec mauris nulla. Sed tristique iaculis diam, ut ultrices sem fringilla nec. Nunc sollicitudin, turpis ac tincidunt porta, lectus tortor luctus sapien, quis dignissim diam orci pharetra urna. Proin sagittis nunc ut urna euismod, quis vehicula risus ullamcorper. Fusce nibh nibh, ultricies eu ante eget, dictum laoreet ex. Integer diam ipsum, egestas vel risus tincidunt, convallis consectetur elit. Etiam auctor erat quis sem dignissim, at malesuada est laoreet. Donec id porta tortor, non auctor metus. Pellentesque bibendum mollis risus. Maecenas cursus ipsum urna, at vestibulum turpis ornare sit amet. Nunc malesuada, dolor non tincidunt laoreet, erat risus faucibus ante, eu viverra elit felis at leo. Maecenas tincidunt mattis diam. first', 2, 3, 'approved', '2025-06-11 12:11:00', '2025-04-23 13:34:05', '2025-06-09 12:07:53', 4),
(3, 'How to Reset Your Password', 'If you forgot your password, follow these steps to reset it. Steps to Reset Password: 1. Go to the Login Page. 2. Click \"Forgot Password?\". 3. Enter your registered email address. 4. Check your inbox for a reset link (valid for 24 hours). 5.Click the link and set a new password.', 2, 4, 'approved', '2025-06-09 15:07:13', '2025-04-23 13:38:49', '2025-06-09 12:06:07', 19),
